from dataiku.base.compat import ImpCompat
from dataiku.core import intercom
from datetime import datetime
from dateutil import parser, tz
import logging
import sys

logger = logging.getLogger("dataiku.core.plugin")

def use_plugin_libs(plugin_id):
    """Add the lib/ folder of the plugin to PYTHONPATH"""
    folders = intercom.jek_or_backend_json_call("plugins/get-lib-folders", data={
        "pluginId" : plugin_id
    })
    
    python_lib = folders.get('pythonLib', '')
    if len(python_lib) > 0:
        if python_lib not in sys.path:
            sys.path.append(python_lib)
    else:
        raise Exception('No python-lib folder defined in this plugin')

def import_from_plugin(plugin_id, package_name):
    """Import a package from the lib/ folder of the plugin and returns the module"""
    folders = intercom.jek_or_backend_json_call("plugins/get-lib-folders", data={
        "pluginId" : plugin_id
    })
    
    python_lib = folders.get('pythonLib', '')
    if len(python_lib) > 0:
        return ImpCompat.find_and_load_module(package_name, [python_lib])
    else:
        raise Exception('No python-lib folder defined in this plugin')

class OAuthCredentials:
    def __init__(self, oauth_credentials):
        self._access_token = oauth_credentials["access_token"]
        self.id_token = oauth_credentials.get("id_token", None)
        self._access_token_expiry_time_utc = oauth_credentials.get("access_token_expiry_time_utc", None)
        self._credentials_ref = oauth_credentials.get("credentials_ref", {})

    @property
    def access_token(self):
        if self.__is_access_token_expired():
            self.refresh_credentials()
            return self._access_token
        else:
            logger.debug("Access token still valid, returning as is")
            return self._access_token

    def refresh_credentials(self):
        logger.debug("Refreshing credentials")
        fresh_creds_result = intercom.backend_json_call(
            "plugins/auth/refresh-credentials", data=self._credentials_ref
        )
        self._access_token = fresh_creds_result["access_token"]
        self.id_token = fresh_creds_result.get("id_token", self.id_token)
        self._access_token_expiry_time_utc = fresh_creds_result.get("access_token_expiry_time_utc", None)

    def __is_access_token_expired(self):
        if self._access_token_expiry_time_utc is None:
            logger.debug("No expiration time set, assuming token does not expire")
            return False
        current_time = datetime.now(tz.tzutc())
        soft_expiration_time_parsed = parser.parse(self._access_token_expiry_time_utc)
        logger.debug("Current time is %s, token expiration time is %s", current_time, soft_expiration_time_parsed)
        return soft_expiration_time_parsed < current_time
